mapper.select:
WITH ephemeral_data AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY process_template_code ORDER BY create_time DESC) AS row_num FROM dp_base.t_dp_base_running_process WHERE delete_flag = false
${processTemplateCode}
) SELECT id, process_code, process_name, table_code, owned_enterprise_code, process_info, process_template_code, process_parameter, remark, create_time, update_time, delete_flag FROM ephemeral_data WHERE row_num = 1;
